fn solve(n: i8) -> Vec<char> {
    // Compute the ones digit of n (n is guaranteed to be in 1..=999)
    let rem = n % 10;

    // Select the appropriate suffix based on the ones digit
    // ‣ {2,4,5,7,9} → "hon\n"
    // ‣ {0,1,6,8}   → "pon\n"
    // ‣ {3}         → "bon\n"
    let suffix = match rem {
        2 | 4 | 5 | 7 | 9 => "hon\n",
        0 | 1 | 6 | 8     => "pon\n",
        3                 => "bon\n",
        // rem is always in 0..=9, so this arm is unreachable
        _                 => unreachable!(),
    };

    // Collect the characters of the suffix into a Vec<char> and return
    suffix.chars().collect()
}

